package org.apache.commons.jxpath.ri.parser;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

import java.io.ByteArrayInputStream;
import java.io.StringReader;

import org.junit.Test;

public class NCNameTests {

    @Test
    public void acceptsOrdinaryNCNames() throws ParseException {
        assertNCName("item", "item");
        assertNCName("_item", "_item");
        assertNCName("item.name-123", "item.name-123");
    }

    @Test
    public void acceptsANameAtTheMaximumPracticalLength() throws ParseException {
        StringBuilder name = new StringBuilder();

        for (int i = 0; i < 1024; i++) {
            name.append('a');
        }

        assertNCName(name.toString(), name.toString());
    }

    @Test
    public void acceptsOperatorsAndSpecialNodeNames() throws ParseException {
        String[] names = {
            "or",
            "and",
            "mod",
            "div",
            "node",
            "text",
            "comment",
            "processing-instruction"
        };

        for (String name : names) {
            assertNCName(name, name);
        }
    }

    @Test
    public void acceptsAllCoreFunctionNames() throws ParseException {
        String[] names = {
            "last",
            "position",
            "count",
            "id",
            "local-name",
            "namespace-uri",
            "name",
            "string",
            "concat",
            "starts-with",
            "ends-with",
            "contains",
            "substring-before",
            "substring-after",
            "substring",
            "string-length",
            "normalize-space",
            "translate",
            "boolean",
            "not",
            "true",
            "false",
            "null",
            "lang",
            "number",
            "sum",
            "floor",
            "ceiling",
            "round",
            "key",
            "format-number"
        };

        for (String name : names) {
            assertNCName(name, name);
        }
    }

    @Test
    public void worksWithReaderConstructor() throws ParseException {
        XPathParser parser = new XPathParser(new StringReader("readerName"));

        assertEquals("readerName", parser.NCName());
        assertEquals("readerName", parser.token.image);
    }

    @Test
    public void worksWithInputStreamConstructor() throws ParseException {
        XPathParser parser = new XPathParser(
                new ByteArrayInputStream("streamName".getBytes()));

        assertEquals("streamName", parser.NCName());
        assertEquals("streamName", parser.token.image);
    }

    @Test
    public void rejectsEmptyInput() {
        assertRejected("");
    }

    @Test
    public void rejectsInputStartingWithAnInvalidToken() {
        assertRejected("1name");
        assertRejected("+");
        assertRejected("(");
    }

    @Test
    public void doesNotConsumeAnInvalidNameAsAnNCName() {
        try {
            new XPathParser(new StringReader("123")).NCName();
            fail("Expected ParseException");
        } catch (ParseException expected) {
            // Expected.
        }
    }

    private static void assertNCName(String input, String expected)
            throws ParseException {
        XPathParser parser = new XPathParser(new StringReader(input));

        assertEquals(expected, parser.NCName());
        assertEquals(expected, parser.token.image);
    }

    private static void assertRejected(String input) {
        try {
            new XPathParser(new StringReader(input)).NCName();
            fail("Expected ParseException for input: " + input);
        } catch (ParseException expected) {
            // Expected.
        }
    }
}

