            "name", "string", "concat", "starts-with", "ends-with", "contains",
            "substring-before", "substring-after", "substring", "string-length",
            "normalize-space", "translate", "boolean", "not", "true", "false",
            "null", "lang", "number", "sum", "floor", "ceiling", "round",
            "key", "format-number"
        };

        for (String functionName : functionNames) {
            XPathParser parser = new XPathParser(new StringReader(functionName));
            assertEquals(functionName, parser.NCName());
            assertEquals(Token.EOF, parser.jj_nt.kind);
        }
    }

    @Test
    public void consumesOnlyTheNCNameAndLeavesFollowingTokenAvailable() throws Exception {
        XPathParser parser = new XPathParser(new StringReader("first second"));

        assertEquals("first", parser.NCName());
        assertNotNull(parser.jj_nt);
        assertEquals("second", parser.jj_nt.image);
    }

    @Test
    public void returnsTheOriginalTokenImage() throws Exception {
        XPathParser parser = new XPathParser(new StringReader("item"));

        String result = parser.NCName();

        assertNotNull(result);
        assertEquals("item", result);
    }

    @Test
    public void rejectsEndOfInput() throws Exception {
        XPathParser parser = new XPathParser(new StringReader(""));

        try {
            parser.NCName();
            fail("Expected ParseException for end of input");
