    public void rejectsInvalidToken() throws Exception {
        XPathParser parser = new XPathParser(new StringReader("'value'"));

        try {
            parser.NCName();
            fail("Expected ParseException for a string literal");
        } catch (ParseException expected) {
            // Expected.
        }
    }

    @Test
    public void rejectsNumericToken() throws Exception {
        XPathParser parser = new XPathParser(new StringReader("123"));

        try {
            parser.NCName();
            fail("Expected ParseException for a numeric literal");
        } catch (ParseException expected) {
